'use strict';
(() => {
const KEY='podarok-pr7-v1', TODAY='2026-10-27';
const $=s=>document.querySelector(s), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2M14 15h2"/>',people:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',idea:'<path d="M9 18h6M10 21h4M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2Z"/>',wallet:'<path d="M20 8H5a2 2 0 0 1 0-4h13v4M3 6v13a2 2 0 0 0 2 2h15V8M20 12h-5v5h5M17 14.5h.01"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m15 5-7 7 7 7"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>',gift:'<path d="M3 8h18v5H3zM5 13v8h14v-8M12 8v13M12 8C3 8 5 0 9 3l3 5Zm0 0c9 0 7-8 3-5l-3 5Z"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',edit:'<path d="m16 3 5 5L8 21H3v-5L16 3ZM14 5l5 5"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',check:'<path d="m5 12 4 4L19 6"/>',link:'<path d="M10 13a5 5 0 0 0 7 .5l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7-.5l-3 3a5 5 0 0 0 7 7l2-2"/>',logout:'<path d="M9 21H3V3h6M13 7l5 5-5 5M7 12h14"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.gift}</svg>`;
const giftArt=`<svg class="line-art auth-drawing" viewBox="0 0 240 180" fill="none" aria-hidden="true"><path d="M39 73h160v34H39zM51 107v64h136v-64M119 73v98M46 107h149" stroke="#537355" stroke-width="2"/><path d="M119 73C57 75 57 11 91 31c19 12 28 42 28 42Zm0 0c62 2 62-62 28-42-19 12-28 42-28 42Z" stroke="#537355" stroke-width="2"/><path d="m24 35 5-6M196 33l6 4M207 125l6-1M23 124l-5 2" stroke="#9a6048" stroke-width="2" stroke-linecap="round"/></svg>`;
const id=()=>crypto.randomUUID?crypto.randomUUID():`id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const statuses={PLANNED:'В планах',BOUGHT:'Куплен',GIVEN:'Подарен'};
const money=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2,minimumFractionDigits:2}).format((n||0)/100);
const exactMoney=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2,minimumFractionDigits:2}).format((n||0)/100);
const parseMoney=(v,optional=false)=>{if(v.trim()===''&&optional)return null;if(!/^\d{1,10}([.,]\d{1,2})?$/.test(v.trim()))return NaN;const [r,k='']=v.trim().replace(',','.').split('.');const n=Number(r)*100+Number(k.padEnd(2,'0'));return n<=999999999999?n:NaN};
const moneyInput=n=>n===null?'':((n||0)/100).toFixed(2).replace('.',',');
const fmtDate=d=>new Date(d+'T12:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'long',timeZone:'UTC'});
const days=d=>Math.round((Date.parse(d+'T00:00:00Z')-Date.parse(TODAY+'T00:00:00Z'))/86400000);
const avatar=(name,tone=0)=>`<span class="avatar tone${tone%4}">${E(name.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase())}</span>`;
const badge=s=>`<span class="badge ${s==='BOUGHT'?'bought':s==='GIVEN'?'given':''}">${s==='BOUGHT'?icon('check'):''}${statuses[s]||E(s)}</span>`;
function seed(){return {version:1,session:'demo@podarok.example',accounts:[{email:'demo@podarok.example',name:'Серафим',timezone:'Asia/Magadan'}],contacts:[{id:'anna',owner:'demo@podarok.example',name:'Анна Миронова',notes:'Любит книги о путешествиях, керамику и уютные вечера.',tone:1},{id:'maksim',owner:'demo@podarok.example',name:'Максим',notes:'Заваривает кофе в воронке. Увлекается фотографией.',tone:2},{id:'mama',owner:'demo@podarok.example',name:'Мама',notes:'Любит сад и вещи, сделанные вручную.',tone:3},{id:'lena',owner:'demo@podarok.example',name:'Елена',notes:'Коллега. Предпочитает полезные подарки.',tone:0}],events:[{id:'e1',contactId:'anna',title:'День рождения',date:'1997-11-03',annual:true},{id:'e2',contactId:'maksim',title:'День рождения',date:'1995-11-07',annual:true},{id:'e3',contactId:'mama',title:'День матери',date:'2026-11-29',annual:false},{id:'e4',contactId:'lena',title:'День рождения',date:'1998-11-18',annual:true}],gifts:[{id:'g1',contactId:'anna',eventId:'e1',title:'Керамическая ваза',description:'Небольшая ваза для полевых цветов.',url:'',planned:350000,actual:null,status:'PLANNED'},{id:'g2',contactId:'maksim',eventId:'e2',title:'Набор кофе из Колумбии',description:'Два разных сорта для воронки.',url:'https://example.com/coffee',planned:240000,actual:219000,status:'BOUGHT'},{id:'g3',contactId:'lena',eventId:'e4',title:'Ежедневник в тканевой обложке',description:'Недатированный, чтобы начать в любой момент.',url:'',planned:180000,actual:null,status:'PLANNED'}],ideas:[{id:'i1',owner:'demo@podarok.example',title:'Книга о тихих путешествиях',description:'Маршруты по небольшим городам и истории местных жителей.',url:'https://example.com/book',cost:220000,assigned:false},{id:'i2',owner:'demo@podarok.example',title:'Мастер-класс по керамике',description:'Подарить время для себя и чашку, сделанную своими руками.',url:'',cost:450000,assigned:false}]}}
let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed()}catch{state=seed()}
let period=30,contactQuery='',ideaQuery='',giftFilter='ALL',toastTimer,dialogReturnFocus,dirty=false;
const user=()=>state.accounts.find(x=>x.email===state.session);
const ownContacts=()=>state.contacts.filter(x=>x.owner===state.session);
const ownIdeas=()=>state.ideas.filter(x=>x.owner===state.session&&!x.assigned);
const contact=cid=>ownContacts().find(x=>x.id===cid);
const ownGifts=()=>state.gifts.filter(x=>contact(x.contactId));
const personName=cid=>contact(cid)?.name||'Контакт';
function notify(text,error=false){const el=$('#toast');clearTimeout(toastTimer);el.textContent=text;el.className='visible'+(error?' error':'');toastTimer=setTimeout(()=>el.className='',4000)}
function commit(change){const next=structuredClone(state);change(next);try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true}catch{notify('Не удалось сохранить. Введённые данные остались в форме.',true);return false}}
function occurrence(ev){if(!ev.annual)return ev.date;const [y,m,d]=ev.date.split('-').map(Number);let year=2026;const dateAt=yy=>`${yy}-${String(m).padStart(2,'0')}-${String(m===2&&d===29&&new Date(Date.UTC(yy,1,29)).getUTCMonth()!==1?28:d).padStart(2,'0')}`;let next=dateAt(year);if(next<TODAY)next=dateAt(year+1);return next}
const upcoming=()=>state.events.filter(e=>contact(e.contactId)).map(e=>({...e,next:occurrence(e)})).filter(e=>e.next>=TODAY&&(!period||days(e.next)<=period)).sort((a,b)=>a.next.localeCompare(b.next));
const options=(items,selected)=>items.map(x=>`<option value="${E(x.id)}" ${x.id===selected?'selected':''}>${E(x.name||x.title)}</option>`).join('');
const input=(name,label,value='',type='text',extra='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${E(value)}" ${extra}><span class="field-error" id="error-${name}"></span></div>`;
const textarea=(name,label,value='')=>`<div class="field"><label for="${name}">${label}</label><textarea id="${name}" name="${name}">${E(value)}</textarea></div>`;
function error(form,name,msg){const el=form.elements[name];if(el){el.setAttribute('aria-invalid','true');el.setAttribute('aria-describedby','error-'+name);const label=form.querySelector('#error-'+name);if(label)label.textContent=msg;if(!form.querySelector('[aria-invalid=true]:focus'))el.focus()}return false}
function clearErrors(form){form.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));form.querySelectorAll('.field-error').forEach(x=>x.textContent='')}
function validTitle(form,name){return form.elements[name].value.trim()?true:error(form,name,'Укажите название.')}
function validURL(form,name='url'){const v=form.elements[name]?.value.trim();if(!v)return true;try{const u=new URL(v);if(['http:','https:'].includes(u.protocol))return true}catch{}return error(form,name,'Ссылка должна начинаться с http:// или https://.')}
function closeDialog(force=false){if(dirty&&!force&&!confirm('Закрыть форму без сохранения изменений?'))return;$('#dialog').close();dirty=false;dialogReturnFocus?.focus()}
function openDialog(title,body){dialogReturnFocus=document.activeElement;dirty=false;$('#dialog').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${E(title)}</h2><button type="button" class="icon-btn" data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button></div>${body}`;$('#dialog').showModal();$('#dialog').querySelector('input,select,textarea')?.focus()}
$('#dialog').addEventListener('cancel',ev=>{ev.preventDefault();closeDialog()});
$('#dialog').addEventListener('input',()=>dirty=true);
function go(path){location.hash='#/'+path}
function empty(title,text,action='',label='Добавить'){return `<div class="empty">${icon('gift')}<h2>${title}</h2><p>${text}</p>${action?`<button class="btn" data-action="${action}">${icon('plus')}${label}</button>`:''}</div>`}
function shell(content,active){const u=user();const links=[['events','calendar','События'],['contacts','people','Контакты'],['inbox','idea','Идеи'],['budget','wallet','Бюджет']];return `<div class="shell"><aside class="sidebar"><a class="brand" href="#/events"><img src="icon.svg" alt="">Подарок</a><p class="brand-sub">Близкие люди.<br>Продуманные подарки.</p><nav aria-label="Основная навигация">${links.map(([path,ic,label])=>`<a href="#/${path}" class="nav-link ${active===path?'active':''}" ${active===path?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${path==='inbox'&&ownIdeas().length?`<span class="nav-count">${ownIdeas().length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="nav-link ${active==='settings'?'active':''}" href="#/settings">${icon('settings')}Настройки</a><a class="profile" href="#/settings">${avatar(u?.name||'С',2)}<div><div class="profile-name">${E(u?.name)}</div><div class="small muted">Личное пространство</div></div></a><p class="prototype-note">УЧЕБНЫЙ ПРОТОТИП · ПР7</p></div></aside><div class="main-wrap"><header class="mobile-top"><a class="brand" href="#/events"><img src="icon.svg" alt="">Подарок</a><a href="#/settings" aria-label="Настройки аккаунта">${avatar(u?.name||'С',2)}</a></header><main id="main" tabindex="-1"><div class="topline"><div class="today"><span class="dot"></span>27 октября 2026 · вторник</div><span class="eyebrow">Планы с заботой</span></div>${content}</main></div></div>`}
function heading(title,subtitle,button=''){return `<div class="page-heading"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${button}</div>`}
function eventView(){const es=upcoming();const gs=ownGifts(),planned=gs.reduce((s,g)=>s+g.planned,0),spent=gs.reduce((s,g)=>s+(g.actual||0),0);return shell(`${heading('Ближайшие поводы','Немного внимания сегодня — приятный сюрприз вовремя.',`<button class="btn" data-action="add-contact">${icon('plus')}Добавить контакт</button>`)}<div class="events-layout"><section><div class="toolbar"><div class="tabs" aria-label="Период событий">${[30,90,0].map(n=>`<button class="tab ${period===n?'selected':''}" data-period="${n}" aria-pressed="${period===n}">${n?n+' дней':'Все будущие'}</button>`).join('')}</div></div><div class="section-heading"><h2>${es.length} ${es.length===1?'событие':es.length<5?'события':'событий'} впереди</h2><span class="small muted">По ближайшей дате</span></div><div class="event-list">${es.length?es.map(e=>{const d=new Date(e.next+'T12:00Z');const g=gs.find(x=>x.eventId===e.id);return `<article class="event-row"><div class="date-tile"><strong>${d.getUTCDate()}</strong><span>${d.toLocaleDateString('ru-RU',{month:'short',timeZone:'UTC'}).replace('.','')}</span></div><div class="event-info"><a class="person-link" href="#/contacts/${e.contactId}">${E(personName(e.contactId))}</a><p class="event-title">${E(e.title)}</p>${g?`<a class="gift-preview" href="#/gifts/${g.id}">${icon('gift')}${E(g.title)}</a>`:`<button class="btn quiet small-btn" data-action="add-gift" data-id="${e.contactId}" data-event="${e.id}">${icon('plus')}Выбрать подарок</button>`}</div><div class="event-end">${g?badge(g.status):'<span class="badge">Подарок не выбран</span>'}<span class="event-days">${days(e.next)===0?'Сегодня':'Через '+days(e.next)+' дн.'}</span></div></article>`}).join(''):empty('Пока нет событий','Добавьте памятную дату в карточке близкого человека.','add-contact','Добавить контакт')}</div></section><aside class="events-aside"><div class="note-panel"><span class="eyebrow">Идеи не теряются</span><h2 style="margin-top:13px">Хорошую мысль<br>лучше сохранить.</h2><p>Получателя можно выбрать позже. Самое важное — не упустить идею.</p>${giftArt}<a class="panel-link" href="#/inbox">К моим идеям ${icon('arrow')}</a></div><div class="side-summary"><h3>Планы на подарки</h3><div class="summary-row"><span class="muted">Запланировано</span><strong>${money(planned)}</strong></div><div class="summary-row"><span class="muted">Уже потрачено</span><strong>${money(spent)}</strong></div><a class="panel-link" href="#/budget">Посмотреть бюджет ${icon('arrow')}</a></div></aside></div>`,'events')}
function contactsView(){const cs=ownContacts().filter(c=>c.name.toLocaleLowerCase('ru').includes(contactQuery.toLocaleLowerCase('ru')));return shell(`${heading('Близкие люди','У каждого свой повод для радости.',`<button class="btn" data-action="add-contact">${icon('plus')}Добавить контакт</button>`)}<div class="toolbar"><div class="search">${icon('search')}<input id="contact-search" aria-label="Поиск по имени" placeholder="Найти по имени" value="${E(contactQuery)}"></div><span class="small muted">${ownContacts().length} контакта</span></div><div class="contacts-grid">${cs.map(c=>{const ev=state.events.filter(x=>x.contactId===c.id).map(x=>({...x,next:occurrence(x)})).filter(x=>x.next>=TODAY).sort((a,b)=>a.next.localeCompare(b.next))[0];const gs=state.gifts.filter(x=>x.contactId===c.id);return `<a class="contact-card" href="#/contacts/${c.id}">${avatar(c.name,c.tone)}<span class="corner">${icon('arrow')}</span><h2>${E(c.name)}</h2><p>${ev?E(ev.title)+' · '+fmtDate(ev.next):'Памятная дата не добавлена'}</p><div class="card-bottom">${icon('gift')}${gs.length?gs.length+' '+(gs.length===1?'план подарка':'плана подарков'):'Пока без подарков'}</div></a>`}).join('')}</div>${!cs.length?empty(contactQuery?'Ничего не найдено':'Кого порадуем первым?',contactQuery?'Попробуйте другое имя или добавьте нового человека.':'Сохраните имя близкого человека, а даты и идеи добавьте позже.','add-contact','Добавить контакт'):''}`,'contacts')}
function contactView(cid){const c=contact(cid);if(!c)return shell(empty('Контакт не найден','Возможно, запись была удалена.'),'contacts');let gs=state.gifts.filter(g=>g.contactId===cid&&(giftFilter==='ALL'||g.status===giftFilter));const es=state.events.filter(e=>e.contactId===cid);return shell(`<a class="back" href="#/contacts">${icon('back')}Все контакты</a><div class="page-heading"><div class="detail-header">${avatar(c.name,c.tone)}<div><h1>${E(c.name)}</h1><p>Подарки, даты и то, что хочется запомнить.</p></div></div><div class="inline-actions"><button class="icon-btn" aria-label="Редактировать контакт" data-action="edit-contact" data-id="${cid}">${icon('edit')}</button><button class="icon-btn" aria-label="Удалить контакт" data-action="delete-contact" data-id="${cid}">${icon('trash')}</button></div></div><div class="detail-columns"><section class="surface"><div class="section-heading"><h2 style="font-size:20px;color:var(--ink)">Подарки</h2><button class="btn small-btn" data-action="add-gift" data-id="${cid}">${icon('plus')}Добавить подарок</button></div><div class="tabs" style="margin-bottom:20px">${[['ALL','Все'],...Object.entries(statuses)].map(([v,t])=>`<button class="tab ${giftFilter===v?'selected':''}" data-status-filter="${v}">${t}</button>`).join('')}</div>${gs.length?gs.map(g=>`<article class="gift-card"><div><a href="#/gifts/${g.id}"><h3>${E(g.title)}</h3></a><div class="gift-meta">${badge(g.status)}${g.eventId?`<span class="small muted">${E(es.find(e=>e.id===g.eventId)?.title||'')}</span>`:''}</div><p class="money">План ${money(g.planned)} · ${g.actual===null?'Расход пока неизвестен':'Потрачено '+money(g.actual)}</p></div><a class="icon-btn" href="#/gifts/${g.id}" aria-label="Открыть подарок ${E(g.title)}">${icon('arrow')}</a></article>`).join(''):empty('Здесь будет хороший подарок','Начните с идеи — ссылку и расходы можно добавить позже.','gift-for-current','Добавить подарок')}</section><aside class="stack"><section class="surface"><div class="section-heading"><h2 style="font-size:19px;color:var(--ink)">Памятные даты</h2><button class="icon-btn" data-action="add-event" data-id="${cid}" aria-label="Добавить дату">${icon('plus')}</button></div>${es.length?es.map(e=>`<div class="date-line"><div><strong class="small">${E(e.title)}</strong><p class="muted">${fmtDate(occurrence(e))}${e.annual?' · каждый год':''}</p></div><button class="icon-btn" data-action="edit-event" data-id="${e.id}" aria-label="Изменить дату ${E(e.title)}">${icon('edit')}</button></div>`).join(''):'<p class="muted small">Добавьте день рождения или другой важный повод.</p>'}</section><section class="surface"><div class="section-heading"><h2 style="font-size:19px;color:var(--ink)">Что важно знать</h2></div><p class="muted" style="white-space:pre-wrap;overflow-wrap:anywhere">${E(c.notes)||'Любимые вещи, увлечения и маленькие подсказки для будущих подарков.'}</p><button class="btn quiet small-btn" data-action="edit-contact" data-id="${cid}">${icon('edit')}Редактировать</button></section></aside></div>`,'contacts')}
function inboxView(){const ideas=ownIdeas().filter(x=>x.title.toLowerCase().includes(ideaQuery.toLowerCase()));return shell(`${heading('Идеи на потом','Сначала хорошая идея. Получатель найдётся.',`<button class="btn" data-action="add-idea">${icon('plus')}Сохранить идею</button>`)}<div class="toolbar"><div class="search">${icon('search')}<input id="idea-search" aria-label="Поиск по названию идеи" placeholder="Найти идею" value="${E(ideaQuery)}"></div><span class="small muted">Без получателя · ${ownIdeas().length}</span></div><div class="inbox-list">${ideas.map(i=>`<article class="idea-card" data-idea="${i.id}"><div><h2>${E(i.title)}</h2><p>${E(i.description)||'Описание можно добавить позже.'}</p><p class="price">${i.cost===null?'Без примерной стоимости':money(i.cost)}${i.url?` · <a href="${E(i.url)}" target="_blank" rel="noopener noreferrer">Открыть ссылку</a>`:''}</p></div><div class="inline-actions"><button class="btn secondary small-btn" data-action="assign-idea" data-id="${i.id}">Выбрать получателя ${icon('arrow')}</button><button class="icon-btn" data-action="edit-idea" data-id="${i.id}" aria-label="Изменить идею ${E(i.title)}">${icon('edit')}</button><button class="icon-btn" data-action="delete-idea" data-id="${i.id}" aria-label="Удалить идею ${E(i.title)}">${icon('trash')}</button></div></article>`).join('')}</div>${!ideas.length?empty(ideaQuery?'Идея не найдена':'Хорошие идеи начинаются здесь',ideaQuery?'Попробуйте другое название.':'Сохраните то, что хочется когда-нибудь подарить.','add-idea','Сохранить идею'):''}`,'inbox')}
function budgetView(){let gs=ownGifts();const planned=gs.reduce((n,g)=>n+g.planned,0),spent=gs.reduce((n,g)=>n+(g.actual||0),0);return shell(`${heading('Бюджет на подарки','Чтобы забота о близких оставалась в ваших планах.')}<div class="budget-summary"><div><p>Запланировано</p><strong>${money(planned)}</strong></div><div><p>Подтверждённые расходы</p><strong>${money(spent)}</strong></div><div><p>План минус известные расходы</p><strong class="${planned-spent<0?'over':''}">${money(planned-spent)}</strong></div></div><p class="small muted" style="margin-bottom:24px">У ${gs.filter(g=>g.actual===null).length} подарков расход пока не указан.</p><div class="budget-row header"><span>Подарок и получатель</span><span style="text-align:end">План</span><span style="text-align:end">Факт</span><span class="remaining" style="text-align:end">Остаток</span></div>${gs.map(g=>`<div class="budget-row"><div><a class="name" href="#/gifts/${g.id}">${E(g.title)}</a><small>${E(personName(g.contactId))}</small></div><span class="value">${money(g.planned)}</span><span class="value ${g.actual!==null&&g.actual>g.planned?'over':''}" style="${g.actual!==null&&g.actual>g.planned?'color:var(--rust)':''}">${g.actual===null?'Не указан':money(g.actual)}</span><span class="value remaining">${g.actual===null?'—':money(g.planned-g.actual)}</span></div>`).join('')}${!gs.length?empty('Пока нет расходов','Добавьте подарок в карточке контакта — его бюджет появится здесь.'):''}`,'budget')}
function giftView(gid,cid,eventId=''){const existing=ownGifts().find(x=>x.id===gid);if(gid&&gid!=='new'&&!existing)return shell(empty('Подарок не найден','Откройте карточку контакта и выберите другой план.'),'contacts');const g=existing||{contactId:cid,eventId,title:'',description:'',url:'',planned:0,actual:null,status:'PLANNED'};const c=contact(g.contactId);if(!c)return shell(empty('Сначала выберите контакт','Подарок должен быть связан с получателем.','add-contact','Добавить контакт'),'contacts');const ev=state.events.filter(e=>e.contactId===g.contactId);return shell(`<div class="form-page"><a class="back" href="#/contacts/${c.id}">${icon('back')}${E(c.name)}</a>${heading(existing?'План подарка':'Новый подарок','Получатель: '+E(c.name))}<form id="gift-form" class="surface" data-id="${existing?.id||''}" data-contact="${c.id}" novalidate>${input('title','Название подарка *',g.title,'text','autocomplete="off"')}${textarea('description','Описание',g.description)}${input('url','Ссылка на подарок',g.url,'text','inputmode="url" placeholder="https://"')}<div class="field"><label for="eventId">Повод</label><select id="eventId" name="eventId"><option value="">Без привязки к событию</option>${options(ev,g.eventId)}</select></div><div class="row-fields">${input('planned','Плановый бюджет, ₽ *',moneyInput(g.planned),'text','inputmode="decimal"')}${input('actual','Фактический расход, ₽',moneyInput(g.actual),'text','inputmode="decimal" placeholder="Пока неизвестен"')}</div><div id="budget-live" class="budget-hint"><span>Остаток</span><strong>${g.actual===null?'Расход пока неизвестен':exactMoney(g.planned-g.actual)}</strong></div><div class="field"><label for="status">Статус</label><select id="status" name="status">${Object.entries(statuses).map(([v,t])=>`<option value="${v}" ${v===g.status?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-actions">${existing?`<button class="icon-btn" type="button" data-action="delete-gift" data-id="${existing.id}" aria-label="Удалить подарок">${icon('trash')}</button>`:''}<a class="btn secondary" href="#/contacts/${c.id}">Отмена</a><button class="btn" type="submit">Сохранить подарок</button></div></form></div>`,'contacts')}
function settingsView(){const u=user();return shell(`${heading('Личное пространство','Профиль и управление данными.')}<div class="settings-grid"><form id="profile-form" class="surface" novalidate><h2>Ваш профиль</h2>${input('displayName','Имя *',u.name)}${input('emailView','Электронная почта',u.email,'email','readonly')}<div class="field"><label for="timezone">Часовой пояс</label><select id="timezone" name="timezone">${['Asia/Magadan','Europe/Moscow','Asia/Vladivostok','UTC'].map(z=>`<option ${z===u.timezone?'selected':''}>${z}</option>`).join('')}</select></div><button class="btn" type="submit">Сохранить профиль</button></form><section class="surface"><h2>Доступ к аккаунту</h2><p class="muted">Завершите сеанс, если пользуетесь общим устройством.</p><button class="btn secondary" data-action="logout">${icon('logout')}Выйти из аккаунта</button><div class="danger-zone surface"><h2>Удаление аккаунта</h2><p>Контакты, памятные даты, идеи и планы будут удалены. Это действие нельзя отменить.</p><button class="btn secondary" data-action="delete-account">Удалить аккаунт</button></div></section></div>`,'settings')}
function authView(mode){const register=mode==='register',restore=mode==='restore',reset=mode==='reset-password';const title=register?'Начнём с знакомства':restore?'Восстановить доступ':reset?'Новый пароль':'С возвращением';return `<div class="auth-shell"><section class="auth-story"><a class="brand" href="#/login"><img src="icon.svg" alt="">Подарок</a><div><h1>Для тех,<br>кто вам<br>дорог.</h1><p>Помните о важных датах, сохраняйте идеи и готовьте подарки без спешки.</p>${giftArt}</div><div class="copyright">Немного внимания меняет многое</div></section><main class="auth-content" id="main"><form class="auth-form" id="auth-form" data-mode="${mode}" novalidate><h2>${title}</h2><p class="intro">${register?'Создайте своё пространство для близких людей.':restore?'Укажите почту, которую использовали при регистрации.':reset?'Не менее 12 символов. Используйте пароль, который ещё не применяли.':'Ваши идеи и планы уже ждут вас.'}</p>${register?input('name','Ваше имя *','','text','autocomplete="name"'):''}${!reset?input('email','Электронная почта *',!register&&!restore?'demo@podarok.example':'','email','autocomplete="email"'):''}${!restore?input('password',reset?'Новый пароль *':'Пароль *','','password','autocomplete="'+(register||reset?'new-password':'current-password')+'" minlength="12" maxlength="128"'):''}${register||reset?'<p class="small muted" style="margin:-9px 0 20px">От 12 до 128 символов.</p>':''}${!register&&!restore&&!reset?'<div class="subactions"><span class="small muted">Личный аккаунт</span><a href="#/restore">Не помню пароль</a></div>':''}<button type="submit" class="btn full">${register?'Создать аккаунт':restore?'Получить инструкцию':reset?'Сохранить новый пароль':'Войти'}</button>${!register&&!restore&&!reset?'<button class="btn secondary full" type="button" style="margin-top:12px" data-action="demo-login">Открыть демо</button>':''}<p class="auth-bottom">${register?'Уже с нами? <a href="#/login">Войти</a>':restore||reset?'<a href="#/login">Вернуться ко входу</a>':'Ещё нет аккаунта? <a href="#/register">Создать</a>'}</p><p class="auth-note">Учебный интерактивный прототип · ПР7</p></form></main></div>`}
function render(){const path=location.hash.replace(/^#\/?/,'')||'events';let html;if(['login','register','restore','reset-password'].includes(path))html=authView(path);else if(!user()){go('login');return}else{const parts=path.split('/');if(parts[0]==='contacts'&&parts[1])html=contactView(parts[1]);else if(parts[0]==='gifts')html=giftView(parts[1],new URLSearchParams(parts[2]||'').get('contact'),new URLSearchParams(parts[2]||'').get('event')||'');else if(path==='contacts')html=contactsView();else if(path==='inbox')html=inboxView();else if(path==='budget')html=budgetView();else if(path==='settings')html=settingsView();else html=eventView()}$('#app').innerHTML=html;document.title=($('#app h1')?.textContent||'Подарок')+' — Подарок';}
function contactDialog(cid=''){const c=cid?contact(cid):{name:'',notes:''};if(!c)return;openDialog(cid?'Редактировать контакт':'Новый контакт',`<form id="contact-form" data-id="${cid}" novalidate>${input('name','Имя *',c.name,'text','autocomplete="off"')}${textarea('notes','Заметки об интересах',c.notes)}<div class="dialog-actions"><button type="button" class="btn secondary" data-action="close-dialog">Отмена</button><button class="btn" type="submit">Сохранить контакт</button></div></form>`)}
function eventDialog(cid,eid=''){const ev=state.events.find(x=>x.id===eid)||{title:'День рождения',date:'',annual:true};openDialog(eid?'Памятная дата':'Добавить дату',`<form id="event-form" data-contact="${cid}" data-id="${eid}" novalidate>${input('title','Название события *',ev.title)}${input('date','Дата *',ev.date,'date')}<label class="check-label"><input type="checkbox" name="annual" ${ev.annual?'checked':''}>Повторять каждый год</label><div class="dialog-actions">${eid?`<button class="icon-btn" type="button" data-action="delete-event" data-id="${eid}" aria-label="Удалить дату">${icon('trash')}</button>`:''}<button type="button" class="btn secondary" data-action="close-dialog">Отмена</button><button class="btn" type="submit">Сохранить дату</button></div></form>`)}
function ideaDialog(iid=''){const i=state.ideas.find(x=>x.id===iid&&x.owner===state.session)||{title:'',description:'',url:'',cost:null};openDialog(iid?'Редактировать идею':'Сохранить идею',`<form id="idea-form" data-id="${iid}" novalidate>${input('title','Название идеи *',i.title)}${textarea('description','Описание',i.description)}${input('url','Ссылка',i.url,'text','inputmode="url" placeholder="https://"')}${input('cost','Примерная стоимость, ₽',moneyInput(i.cost),'text','inputmode="decimal" placeholder="Необязательно"')}<div class="dialog-actions"><button type="button" class="btn secondary" data-action="close-dialog">Отмена</button><button class="btn" type="submit">Сохранить идею</button></div></form>`)}
function assignDialog(iid){const i=ownIdeas().find(x=>x.id===iid);if(!i)return;const cs=ownContacts();openDialog('Кому подарим?',cs.length?`<form id="assign-form" data-id="${iid}"><p>Идея «${E(i.title)}» станет планом подарка у выбранного человека.</p><div class="field"><label for="contactId">Получатель</label><select id="contactId" name="contactId">${options(cs)}</select></div><div class="dialog-actions"><button type="button" class="btn secondary" data-action="close-dialog">Отмена</button><button class="btn" type="submit">Назначить подарок</button></div></form>`:`<p>Сначала добавьте человека, которому хотите сделать подарок.</p><button class="btn" data-action="add-contact">${icon('plus')}Добавить контакт</button>`)}
let pendingDelete;
function confirmDelete(kind,oid){let title,body;const c=contact(oid);if(kind==='contact'&&c){const es=state.events.filter(e=>e.contactId===oid).length,gs=state.gifts.filter(g=>g.contactId===oid).length;title='Удалить контакт?';body=`Контакт «${E(c.name)}», его даты (${es}) и планы подарков (${gs}) будут удалены. Остальные контакты останутся.`}else if(kind==='account'){title='Удалить аккаунт?';body=`Все ваши контакты (${ownContacts().length}), даты, идеи и подарки будут удалены. Восстановить их не получится.`}else{title=kind==='gift'?'Удалить подарок?':kind==='event'?'Удалить дату?':'Удалить идею?';body='Запись будет удалена. Остальные данные останутся.'}pendingDelete={kind,oid};openDialog(title,`<form id="delete-form" novalidate><p>${body}</p>${kind==='account'?input('password','Подтвердите пароль *','','password'):''}<div class="dialog-actions"><button class="btn secondary" type="button" data-action="close-dialog">Оставить</button><button class="btn danger" type="submit">${kind==='account'?'Удалить аккаунт':'Удалить'}</button></div></form>`)}
document.addEventListener('click',ev=>{const periodBtn=ev.target.closest('[data-period]');if(periodBtn){period=Number(periodBtn.dataset.period);render();return}const filter=ev.target.closest('[data-status-filter]');if(filter){giftFilter=filter.dataset.statusFilter;render();return}const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,oid=el.dataset.id;if(a==='close-dialog')closeDialog();if(a==='add-contact'||a==='edit-contact'){if($('#dialog').open)closeDialog(true);contactDialog(a==='edit-contact'?oid:'')}if(a==='add-event')eventDialog(oid);if(a==='edit-event'){const e=state.events.find(x=>x.id===oid);if(e&&contact(e.contactId))eventDialog(e.contactId,oid)}if(a==='add-idea'||a==='edit-idea')ideaDialog(oid);if(a==='assign-idea')assignDialog(oid);if(a==='add-gift')go(`gifts/new/contact=${oid}&event=${el.dataset.event||''}`);if(a==='gift-for-current')go(`gifts/new/contact=${location.hash.split('/')[2]}`);if(a.startsWith('delete-'))confirmDelete(a.replace('delete-',''),oid);if(a==='logout'){if(commit(s=>s.session=null)){go('login');notify('Вы вышли из аккаунта.')}}if(a==='demo-login'){if(commit(s=>{if(!s.accounts.some(x=>x.email==='demo@podarok.example'))Object.assign(s,seed());s.session='demo@podarok.example'})){go('events')}}});
document.addEventListener('input',ev=>{if(ev.target.id==='contact-search'){const pos=ev.target.selectionStart;contactQuery=ev.target.value;render();$('#contact-search').focus();$('#contact-search').setSelectionRange(pos,pos)}if(ev.target.id==='idea-search'){const pos=ev.target.selectionStart;ideaQuery=ev.target.value;render();$('#idea-search').focus();$('#idea-search').setSelectionRange(pos,pos)}if(ev.target.closest('#gift-form')&&['planned','actual'].includes(ev.target.name)){const f=$('#gift-form'),p=parseMoney(f.elements.planned.value),a=parseMoney(f.elements.actual.value,true);if(!Number.isNaN(p)&&!Number.isNaN(a)){const over=a!==null&&a>p;$('#budget-live').className='budget-hint'+(over?' over':'');$('#budget-live').innerHTML=`<span>${over?'Перерасход':'Остаток'}</span><strong>${a===null?'Расход пока неизвестен':exactMoney(over?a-p:p-a)}</strong>`}}});
document.addEventListener('submit',ev=>{ev.preventDefault();const f=ev.target;if(!(f instanceof HTMLFormElement))return;clearErrors(f);
if(f.id==='contact-form'){if(!f.elements.name.value.trim()){error(f,'name','Укажите имя контакта.');return}const cid=f.dataset.id||id(),isNew=!f.dataset.id;const ok=commit(s=>{const data={name:f.elements.name.value.trim(),notes:f.elements.notes.value.trim()};if(isNew)s.contacts.push({id:cid,owner:s.session,tone:s.contacts.length%4,...data});else Object.assign(s.contacts.find(c=>c.id===cid),data)});if(ok){closeDialog(true);go('contacts/'+cid);render();notify(isNew?'Контакт добавлен. Теперь можно сохранить памятную дату.':'Контакт обновлён.')}return}
if(f.id==='event-form'){if(!validTitle(f,'title'))return;const date=f.elements.date.value;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||Number.isNaN(Date.parse(date+'T12:00Z'))){error(f,'date','Укажите существующую календарную дату.');return}const eid=f.dataset.id||id();if(commit(s=>{const data={id:eid,contactId:f.dataset.contact,title:f.elements.title.value.trim(),date,annual:f.elements.annual.checked};if(f.dataset.id)Object.assign(s.events.find(e=>e.id===eid),data);else s.events.push(data)})){closeDialog(true);render();notify('Памятная дата сохранена.')}return}
if(f.id==='idea-form'){if(!validTitle(f,'title')||!validURL(f))return;const cost=parseMoney(f.elements.cost.value,true);if(Number.isNaN(cost)){error(f,'cost','Введите неотрицательную сумму, не более двух знаков после запятой.');return}const iid=f.dataset.id||id();if(commit(s=>{const data={title:f.elements.title.value.trim(),description:f.elements.description.value.trim(),url:f.elements.url.value.trim(),cost};if(f.dataset.id)Object.assign(s.ideas.find(x=>x.id===iid),data);else s.ideas.push({id:iid,owner:s.session,assigned:false,...data})})){closeDialog(true);render();notify('Идея сохранена. Получателя можно выбрать позже.')}return}
if(f.id==='assign-form'){const iid=f.dataset.id,cid=f.elements.contactId.value;const idea=ownIdeas().find(x=>x.id===iid);if(!idea||!contact(cid)){notify('Идея уже назначена или контакт недоступен.',true);return}const gid=id();if(commit(s=>{const i=s.ideas.find(x=>x.id===iid);if(i.assigned||s.gifts.some(g=>g.sourceId===iid))return;i.assigned=true;s.gifts.push({id:gid,sourceId:iid,contactId:cid,eventId:'',title:i.title,description:i.description,url:i.url,planned:0,actual:null,status:'PLANNED'})})){closeDialog(true);go('contacts/'+cid);notify('Идея стала планом подарка.')}return}
if(f.id==='gift-form'){if(!validTitle(f,'title')||!validURL(f))return;const planned=parseMoney(f.elements.planned.value),actual=parseMoney(f.elements.actual.value,true);if(Number.isNaN(planned)){error(f,'planned','Введите сумму от 0 до 9 999 999 999,99 ₽, не более двух знаков.');return}if(Number.isNaN(actual)){error(f,'actual','Введите неотрицательную сумму, не более двух знаков.');return}const gid=f.dataset.id||id();if(commit(s=>{const data={title:f.elements.title.value.trim(),description:f.elements.description.value.trim(),url:f.elements.url.value.trim(),planned,actual,status:f.elements.status.value,eventId:f.elements.eventId.value,contactId:f.dataset.contact};if(f.dataset.id)Object.assign(s.gifts.find(g=>g.id===gid),data);else s.gifts.push({id:gid,...data})})){go('contacts/'+f.dataset.contact);notify('Подарок сохранён.')}return}
if(f.id==='profile-form'){if(!f.elements.displayName.value.trim()){error(f,'displayName','Укажите имя.');return}if(commit(s=>Object.assign(s.accounts.find(a=>a.email===s.session),{name:f.elements.displayName.value.trim(),timezone:f.elements.timezone.value}))){render();notify('Профиль сохранён.')}return}
if(f.id==='auth-form'){const mode=f.dataset.mode;const email=f.elements.email?.value.trim().toLowerCase();if(mode==='register'&&!f.elements.name.value.trim()){error(f,'name','Укажите ваше имя.');return}if(mode!=='reset-password'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){error(f,'email','Введите корректную электронную почту.');return}if(mode!=='restore'&&(f.elements.password.value.length<12||f.elements.password.value.length>128)){error(f,'password','Пароль должен содержать от 12 до 128 символов.');return}if(mode==='restore'){openDialog('Проверьте почту','<p>Если аккаунт с таким адресом существует, мы отправили инструкцию для восстановления.</p><a class="btn full" href="#/reset-password" data-action="close-dialog">Открыть шаг нового пароля</a>');return}if(mode==='reset-password'){go('login');notify('Пароль обновлён. Войдите в аккаунт.');return}if(mode==='register'){if(state.accounts.some(a=>a.email===email)){error(f,'email','Этот адрес уже используется. Войдите или восстановите доступ.');return}if(commit(s=>s.accounts.push({email,name:f.elements.name.value.trim(),timezone:'Asia/Magadan'}))){go('login');notify('Аккаунт создан. Теперь можно войти.')}return}if(!state.accounts.some(a=>a.email===email)){error(f,'email','Не удалось войти. Проверьте почту и пароль.');return}if(commit(s=>s.session=email)){go('events');notify('Рады вас видеть.')}return}
if(f.id==='delete-form'){const {kind,oid}=pendingDelete;if(kind==='account'&&f.elements.password.value.length<12){error(f,'password','Введите пароль от 12 символов.');return}let route='';if(kind==='contact')route='contacts';if(kind==='gift')route='contacts/'+state.gifts.find(g=>g.id===oid)?.contactId;if(kind==='idea')route='inbox';if(kind==='account')route='login';if(commit(s=>{if(kind==='contact'||kind==='account'){const cids=s.contacts.filter(c=>kind==='account'?c.owner===s.session:c.id===oid).map(c=>c.id);s.contacts=s.contacts.filter(c=>!cids.includes(c.id));s.events=s.events.filter(e=>!cids.includes(e.contactId));s.gifts=s.gifts.filter(g=>!cids.includes(g.contactId))}if(kind==='gift')s.gifts=s.gifts.filter(g=>g.id!==oid);if(kind==='idea')s.ideas=s.ideas.filter(i=>i.id!==oid);if(kind==='event'){s.events=s.events.filter(e=>e.id!==oid);s.gifts.filter(g=>g.eventId===oid).forEach(g=>g.eventId='')}if(kind==='account'){s.ideas=s.ideas.filter(i=>i.owner!==s.session);s.accounts=s.accounts.filter(a=>a.email!==s.session);s.session=null}})){closeDialog(true);if(route)go(route);render();notify(kind==='contact'?'Контакт и связанные записи удалены.':kind==='account'?'Аккаунт удалён.':'Запись удалена.')}return}
});
document.addEventListener('input',ev=>{const f=ev.target.closest('#gift-form');if(f)f.dataset.dirty='true'});
document.addEventListener('click',ev=>{const link=ev.target.closest('a[href^="#/"]');const f=$('#gift-form');if(link&&f?.dataset.dirty==='true'&&link.hash!==location.hash&&!confirm('Перейти без сохранения изменений подарка?')){ev.preventDefault();ev.stopImmediatePropagation()}},true);
window.addEventListener('beforeunload',ev=>{if($('#gift-form')?.dataset.dirty==='true'){ev.preventDefault();ev.returnValue=''}});
window.addEventListener('hashchange',()=>{if($('#dialog').open)closeDialog(true);render();window.scrollTo({top:0,behavior:'instant'})});
window.addEventListener('storage',ev=>{if(ev.key===KEY){try{state=JSON.parse(ev.newValue)||seed();render()}catch{notify('Не удалось прочитать обновлённые данные.',true)}}});
if(!location.hash)location.hash='#/events';else render();
})();
